const body = $json.body || $json;
const requestId = body.request_id || body.requestId || $executionId;
const action = body.action || 'sendMessage';
const message = body.user_message || body.chatInput || '';
if (!message || typeof message !== 'string') {
  return [{ json: { valid: false, request_id: requestId, action, error: { type: 'BAD_REQUEST', retryable: false }, message: 'user_message is required' } }];
}
return [{ json: { valid: true, request_id: requestId, action, user_message: message, session_id: body.session_id || body.sessionId, metadata: body.metadata || {} } }];
